import { createRoot } from "react-dom/client";
import BoopItGame from "./BoopItComponent";

const boop_it_elem = document.getElementById("boop-it-root");
if (boop_it_elem) {
  const root = createRoot(boop_it_elem);
  root.render(<BoopItGame />);
} else {
  console.error(
    "Could not mount because #boop-it-root was nowhere to be found",
  );
}
