import { markLocalTaskSolved } from "@hunt/puzzle-components";
import { Play, RotateCcw, Trophy } from "lucide-react";
import React, { useState, useEffect, useRef, useCallback } from "react";
import dog from "./assets/dog.png";
import { WINNING_SCORE } from "./shared";

// Silhouette taken from https://pixabay.com/vectors/dog-dachshund-race-pet-hair-1418283/
// Artist explicitly says that it can be used without attribution.

type Command = {
  id: string;
  text: string;
  color: string;
  instruction: string;
};

// Constants
const RUB_THRESHOLD = 30; // Amount of movement needed for rubs
const RUB_SENSITIVITY = 1.5; // Progress increment per pointer move event
const SPEED_INCREASE_PER_POINT = 50; // Milliseconds reduced per point scored
const MAX_SPEED_REDUCTION = 2000; // Maximum milliseconds that can be reduced
const TIMER_UPDATE_INTERVAL_MS = 50; // Timer update frequency in milliseconds

// Bowl and collision constants for "Feed It" command
const BOWL_X = 340; // X position of the bowl
const BOWL_Y = 280; // Y position of the bowl for collision detection
const COLLISION_RADIUS = 60; // Collision detection radius for food drop
const HIGHLIGHT_RADIUS = 50; // Visual highlight zone radius

const COMMANDS: Command[] = [
  {
    id: "boop",
    text: "Boop It!",
    color: "text-pink-500",
    instruction: "Tap the nose!",
  },
  {
    id: "scritch",
    text: "Scritch It!",
    color: "text-purple-500",
    instruction: "Scritch the ears!",
  },
  {
    id: "pet",
    text: "Pet It!",
    color: "text-blue-500",
    instruction: "Pet the dog!",
  },
  {
    id: "belly",
    text: "Belly Rub It!",
    color: "text-orange-500",
    instruction: "Rub the belly!",
  },
  {
    id: "feed",
    text: "Feed It!",
    color: "text-green-500",
    instruction: "Drag food to bowl!",
  },
];

const BoopItGame = () => {
  // Game State
  const [gameState, setGameState] = useState("menu"); // menu, playing, gameover, win
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(100);
  const [currentCommand, setCurrentCommand] = useState<Command | null>(null);
  const [feedback, setFeedback] = useState("");
  const [rubProgress, setRubProgress] = useState(0);

  // Dragging state for "Feed It"
  const [dragPosition, setDragPosition] = useState({ x: 0, y: 0 });
  const [isDraggingFood, setIsDraggingFood] = useState(false);

  // Refs for timer
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const maxTimeRef = useRef(3000); // Start with 3 seconds
  const scoreRef = useRef(score); // Track current score for callbacks
  scoreRef.current = score;
  const rubProcessedRef = useRef(false); // Prevent multiple success calls during rub
  const inFeedbackDelayRef = useRef(false); // Prevent actions during feedback delay period
  const handleFoodDragEndRef = useRef<(() => void) | null>(null);
  const nextCommandRef = useRef<(() => void) | null>(null); // Track current nextCommand for callbacks
  const svgRef = useRef<SVGSVGElement | null>(null); // Store SVG element reference for drag operations
  const dragPositionRef = useRef(dragPosition); // Track current drag position for callbacks

  // --- Game Logic ---

  const startGame = () => {
    setScore(0);
    setGameState("playing");
    setFeedback("");

    maxTimeRef.current = 3000;
    nextCommand();
  };

  const gameOver = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);
    // Use scoreRef to get the current score (avoids stale closure)
    const currentScore = scoreRef.current;
    // Show win screen if player reached target score, otherwise game over
    if (currentScore >= WINNING_SCORE) {
      setGameState("win");
      markLocalTaskSolved("boop_it");
    } else {
      setGameState("gameover");
    }
    // Reset interaction state when the game ends
    setRubProgress(0);
    setDragPosition({ x: 0, y: 0 });
    setIsDraggingFood(false);
    rubProcessedRef.current = false;
    setCurrentCommand(null);
  }, []);

  const nextCommand = useCallback(() => {
    // Reset interaction states
    setRubProgress(0);
    setDragPosition({ x: 0, y: 0 });
    setIsDraggingFood(false);
    rubProcessedRef.current = false; // Allow new rub to trigger success
    inFeedbackDelayRef.current = false; // Reset feedback delay guard

    // Pick random command (exclude current to prevent repeats)
    const availableCommands = currentCommand
      ? COMMANDS.filter((cmd) => cmd.id !== currentCommand.id)
      : COMMANDS;

    const nextCmd =
      availableCommands[Math.floor(Math.random() * availableCommands.length)];

    setCurrentCommand(nextCmd);

    // Calculate time allowed based on score (gets faster)
    // Cap minimum time at 1 second
    const speedUp = Math.min(
      MAX_SPEED_REDUCTION,
      score * SPEED_INCREASE_PER_POINT,
    );
    const newMaxTime = Math.max(1000, 3000 - speedUp);
    maxTimeRef.current = newMaxTime;
    setTimeLeft(100);

    // Start Timer
    if (timerRef.current) clearInterval(timerRef.current);
    const startTime = Date.now();

    timerRef.current = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const percentLeft = 100 - (elapsed / newMaxTime) * 100;

      if (percentLeft <= 0) {
        setTimeLeft(0);
        if (timerRef.current) clearInterval(timerRef.current);
        gameOver();
      } else {
        setTimeLeft(percentLeft);
      }
    }, TIMER_UPDATE_INTERVAL_MS);
  }, [currentCommand, score, gameOver]);

  // Keep nextCommandRef current to avoid stale closures
  nextCommandRef.current = nextCommand;

  const success = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);
    // Use scoreRef to get the current score (avoids stale closure)
    const newScore = scoreRef.current + 1;
    setScore(newScore);

    setFeedback("Good Dog!");

    // Set guard to prevent actions during feedback delay
    inFeedbackDelayRef.current = true;

    // Brief delay before next command for visual feedback
    setTimeout(() => {
      setFeedback("");
      // Use nextCommandRef to avoid stale closure
      nextCommandRef.current?.();
    }, 200);
  }, []);

  // --- Interaction Handlers ---

  const handleBoop = () => {
    if (gameState !== "playing" || currentCommand?.id !== "boop") return;
    if (inFeedbackDelayRef.current) return; // Prevent action during feedback delay
    success();
  };

  // Generic handler for scrubbing interactions (Scritch, Pet, Belly)
  const handleRubMove = (e: React.PointerEvent, targetId: string) => {
    if (gameState !== "playing" || currentCommand?.id !== targetId) return;

    // Require click/touch (primary button) to be active for scrubbing
    if (e.buttons !== 1) return;

    // Prevent multiple success calls
    if (rubProcessedRef.current) return;

    // Prevent action during feedback delay
    if (inFeedbackDelayRef.current) return;

    // We just count events as simple movement detection
    // In a real pointer event, we might calculate delta distance,
    // but frequency of move events is a decent proxy for "rubbing"
    setRubProgress((prev) => {
      const newProgress = prev + RUB_SENSITIVITY;
      if (newProgress >= RUB_THRESHOLD) {
        // Mark as processed to prevent duplicate calls
        rubProcessedRef.current = true;
        // Show 100% briefly before triggering success
        setTimeout(() => {
          success();
        }, 100);
        return RUB_THRESHOLD; // Show full progress
      }
      return newProgress;
    });
  };

  // Food Dragging Logic
  const handleFoodDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    if (gameState !== "playing" || currentCommand?.id !== "feed") return;
    e.preventDefault(); // Prevent scrolling on touch
    setIsDraggingFood(true);
  };

  const handleFoodDragMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingFood) return;

    // Calculate position relative to the SVG container would be ideal,
    // but for simplicity we'll just track raw pointer movement relative to start
    // A simplified approach for SVG dragging:

    // Use the cached SVG element reference
    const svg = svgRef.current;
    if (!svg) return;

    const pt = svg.createSVGPoint();
    // Support both mouse and touch
    if ("touches" in e) {
      // Early return if no touches are present
      if (e.touches.length === 0) return;
      pt.x = e.touches[0].clientX;
      pt.y = e.touches[0].clientY;
    } else {
      pt.x = e.clientX;
      pt.y = e.clientY;
    }

    // Transform to SVG coords
    const screenCTM = svg.getScreenCTM();
    if (!screenCTM) return;
    const svgP = pt.matrixTransform(screenCTM.inverse());

    // Clamp or just set
    setDragPosition({ x: svgP.x, y: svgP.y });
  };

  // Keep dragPositionRef in sync with dragPosition state
  useEffect(() => {
    dragPositionRef.current = dragPosition;
  }, [dragPosition]);

  // Update the ref with the latest callback
  useEffect(() => {
    handleFoodDragEndRef.current = () => {
      if (!isDraggingFood) return;
      setIsDraggingFood(false);

      // Prevent action during feedback delay
      if (inFeedbackDelayRef.current) {
        // Snap back if in feedback delay
        setDragPosition({ x: 0, y: 0 });
        return;
      }

      // Check collision with bowl - read from ref to get current position
      const currentDragPosition = dragPositionRef.current;
      const dist = Math.sqrt(
        Math.pow(currentDragPosition.x - BOWL_X, 2) +
          Math.pow(currentDragPosition.y - BOWL_Y, 2),
      );

      if (dist < COLLISION_RADIUS) {
        success();
      } else {
        // Snap back
        setDragPosition({ x: 0, y: 0 });
      }
    };
  }, [isDraggingFood, success]);

  // Global pointer up for dragging release - stable event listeners
  useEffect(() => {
    const handleEvent = () => {
      handleFoodDragEndRef.current?.();
    };

    window.addEventListener("mouseup", handleEvent);
    window.addEventListener("touchend", handleEvent);
    return () => {
      window.removeEventListener("mouseup", handleEvent);
      window.removeEventListener("touchend", handleEvent);
    };
  }, []); // Empty deps - listeners are stable, ref keeps callback current

  // --- SVG Components ---

  // Helper to determine active styles
  const getActiveStyle = (id: string) => {
    if (gameState !== "playing") return "fill-transparent opacity-0"; // Hidden/inactive state
    if (currentCommand?.id === id)
      return "fill-yellow-400 opacity-40 animate-pulse cursor-pointer"; // Active target
    return "fill-transparent cursor-default"; // Inactive zone
  };

  return (
    <div className="flex flex-col items-center h-full w-full bg-slate-900 text-white font-sans overflow-hidden select-none touch-none">
      {/* --- Header / HUD --- */}
      <div className="w-full max-w-md px-4 py-4 flex justify-between items-center z-10">
        <div className="flex flex-col">
          <span className="text-xs text-slate-400 uppercase tracking-widest">
            Score
          </span>
          <span className="text-2xl font-bold font-mono">{score}</span>
        </div>

        <div className="flex flex-col items-center">
          {gameState === "playing" ? (
            <div
              className={`text-2xl font-black tracking-tighter uppercase transition-all duration-100 transform ${currentCommand ? "scale-110" : "scale-100"} ${currentCommand?.color || "text-white"}`}
            >
              {feedback || currentCommand?.text}
            </div>
          ) : (
            <div className="text-2xl font-black tracking-tighter text-yellow-500">
              BOOP IT
            </div>
          )}
        </div>

        {/* Target score display */}
        <div className="flex flex-col items-end">
          <span className="text-xs text-slate-400 uppercase tracking-widest">
            Target
          </span>
          <span className="text-2xl font-bold font-mono text-yellow-500">
            {WINNING_SCORE}
          </span>
        </div>
      </div>

      {/* --- Timer Bar --- */}
      <div className="w-full max-w-md px-4 mb-2">
        <div className="h-4 bg-slate-800 rounded-full overflow-hidden border border-slate-700 shadow-inner">
          <div
            className={`h-full ${timeLeft < 30 ? "bg-red-500" : "bg-green-500"}`}
            style={{ width: `${timeLeft}%` }}
          />
        </div>

        {/* Rub Progress Indicator - shows for scritch, pet, belly commands */}
        {gameState === "playing" &&
          currentCommand &&
          ["scritch", "pet", "belly"].includes(currentCommand.id) && (
            <div className="mt-2">
              <div className="h-2 bg-slate-800 rounded-full overflow-hidden border border-slate-600">
                <div
                  className="h-full bg-purple-500 transition-all duration-75"
                  style={{ width: `${(rubProgress / RUB_THRESHOLD) * 100}%` }}
                />
              </div>
              <p className="text-center text-purple-400 text-xs mt-1">
                Progress
              </p>
            </div>
          )}

        {gameState === "playing" && currentCommand && (
          <p className="text-center text-slate-400 text-sm mt-2 animate-bounce">
            {currentCommand.instruction}
          </p>
        )}
      </div>

      {/* --- Main Game Area (SVG) --- */}
      <div className="relative w-full max-w-md aspect-[5/4] bg-slate-800/50 rounded-3xl border-4 border-slate-700 shadow-2xl overflow-hidden m-4">
        {/* SVG Canvas */}
        <svg
          id="game-canvas"
          ref={svgRef}
          viewBox="0 0 400 320"
          className="w-full h-full cursor-crosshair touch-none"
          onMouseMove={(e) => {
            if (isDraggingFood) handleFoodDragMove(e);
          }}
          onTouchMove={(e) => {
            if (isDraggingFood) handleFoodDragMove(e);
          }}
        >
          {/* --- Room Background Elements --- */}
          <rect
            x="0"
            y="160"
            width="400"
            height="160"
            className="fill-slate-700"
          />

          {/* --- The Dog (Replaced with Image) --- */}
          {/* NOTE: This image tag is placed approximately where the dog should be.
                You may need to adjust x, y, width, and height to make your specific image fit well.
            */}
          <image
            href={dog}
            x="40"
            y="40"
            width="280"
            height="280"
            preserveAspectRatio="xMidYMid meet"
            aria-label="Dog silhouette"
          />

          {/* --- Interactive Zones (Invisible or Glowing Overlays) --- */}
          {/* NOTE: These zones were originally positioned for the drawn dog.
                You might need to adjust their 'transform' or coordinates to match your photo.
            */}

          {/* 1. Pet It (Back/Top of dog) */}
          <g transform="translate(0, 0)">
            <ellipse
              cx="165"
              cy="160"
              rx="70"
              ry="20"
              className={getActiveStyle("pet")}
              role="button"
              aria-label="Pet the dog's back"
              onPointerDown={(e) => {
                handleRubMove(e, "pet");
              }}
              onPointerMove={(e) => {
                handleRubMove(e, "pet");
              }}
            />
          </g>

          {/* 2. Belly Rub It (Belly/Underside) */}
          <g transform="translate(0, 0)">
            <ellipse
              cx="170"
              cy="210"
              rx="60"
              ry="18"
              className={getActiveStyle("belly")}
              role="button"
              aria-label="Rub the dog's belly"
              onPointerDown={(e) => {
                handleRubMove(e, "belly");
              }}
              onPointerMove={(e) => {
                handleRubMove(e, "belly");
              }}
            />
          </g>

          {/* 3. Scritch It (Ears) */}
          <g transform="translate(0, 0)">
            <ellipse
              cx="270"
              cy="130"
              rx="15"
              ry="30"
              className={getActiveStyle("scritch")}
              role="button"
              aria-label="Scritch the dog's ears"
              onPointerDown={(e) => {
                handleRubMove(e, "scritch");
              }}
              onPointerMove={(e) => {
                handleRubMove(e, "scritch");
              }}
            />
          </g>

          {/* 4. Boop It (Nose) */}
          <g transform="translate(0, 0)">
            <circle
              cx="315"
              cy="130"
              r="20"
              className={getActiveStyle("boop")}
              role="button"
              aria-label="Boop the dog's nose"
              onClick={handleBoop}
            />
          </g>

          {/* 5. Feed It (Bowl and Bag) */}
          {/* Bowl Target Zone */}
          <g transform={`translate(${BOWL_X}, ${BOWL_Y - 20})`}>
            <ellipse
              cx="0"
              cy="20"
              rx="40"
              ry="15"
              className="fill-slate-800 opacity-50"
            />
            <path
              d="M -30 20 L -35 0 L 35 0 L 30 20 Z"
              className="fill-red-600"
            />
            <ellipse cx="0" cy="0" rx="35" ry="10" className="fill-red-500" />
            <ellipse
              cx="0"
              cy="2"
              rx="30"
              ry="8"
              className="fill-amber-900"
            />{" "}
            {/* Food inside */}
            {/* Highlight zone for dropping */}
            <circle
              r={HIGHLIGHT_RADIUS}
              className={`${currentCommand?.id === "feed" ? "stroke-green-400 stroke-2 stroke-dashed opacity-50" : "opacity-0"} fill-transparent pointer-events-none`}
            />
          </g>

          {/* Draggable Food Bag */}
          {currentCommand?.id === "feed" && (
            <g
              transform={`translate(${isDraggingFood ? dragPosition.x : 60}, ${isDraggingFood ? dragPosition.y : 290})`}
              className="cursor-grab active:cursor-grabbing"
              role="button"
              aria-label="Drag food to the dog's bowl"
              onMouseDown={handleFoodDragStart}
              onTouchStart={handleFoodDragStart}
            >
              <rect
                x="-20"
                y="-30"
                width="40"
                height="50"
                rx="5"
                className="fill-green-600 stroke-white stroke-2"
              />
              <text
                x="0"
                y="0"
                textAnchor="middle"
                className="fill-white text-xs font-bold pointer-events-none"
              >
                FOOD
              </text>
              {/* Drag Handle */}
              <circle r="25" className="fill-transparent" />
            </g>
          )}
        </svg>

        {/* --- Overlays --- */}

        {/* Menu Screen */}
        {gameState === "menu" && (
          <div className="absolute inset-0 bg-slate-900/80 flex flex-col items-center justify-center p-6 text-center backdrop-blur-sm">
            <h1 className="text-5xl font-black text-yellow-500 mb-2 tracking-tighter transform-gpu drop-shadow-lg">
              BOOP IT!
            </h1>
            <p className="text-slate-300 mb-8 max-w-xs">
              Listen to the commands and react fast. Don&apos;t make the puppy
              sad!
            </p>
            <button
              onClick={startGame}
              className="group relative px-8 py-4 bg-yellow-500 hover:bg-yellow-400 text-slate-900 font-black text-xl rounded-full transition-all transform hover:scale-105 active:scale-95 shadow-lg flex items-center gap-3"
            >
              <Play className="w-6 h-6 fill-current" />
              PLAY NOW
              {/* Button shine effect */}
              <div className="absolute inset-0 rounded-full overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-white/20 -translate-x-full group-hover:animate-shine" />
              </div>
            </button>
          </div>
        )}

        {/* Game Over Screen */}
        {gameState === "gameover" && (
          <div className="absolute inset-0 bg-slate-900/90 flex flex-col items-center justify-center p-6 text-center backdrop-blur-md z-20">
            <h2 className="text-4xl font-black text-white mb-2">GAME OVER</h2>

            <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 mb-8 w-full max-w-xs">
              <div className="flex justify-between items-center mb-2">
                <span className="text-slate-400">Score</span>
                <span className="text-2xl font-bold text-white">{score}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Target</span>
                <span className="text-2xl font-bold text-yellow-500">
                  {WINNING_SCORE}
                </span>
              </div>
            </div>

            <button
              onClick={startGame}
              className="px-8 py-4 bg-white hover:bg-slate-200 text-slate-900 font-black text-xl rounded-full transition-all transform hover:scale-105 active:scale-95 shadow-lg flex items-center gap-3"
            >
              <RotateCcw className="w-6 h-6" />
              TRY AGAIN
            </button>
          </div>
        )}

        {/* Win Screen */}
        {gameState === "win" && (
          <div className="absolute inset-0 bg-slate-900/90 flex flex-col items-center justify-center p-6 text-center backdrop-blur-md z-20">
            <Trophy className="w-16 h-16 text-yellow-500 mb-4 animate-bounce" />
            <h2 className="text-4xl font-black text-yellow-500 mb-2">
              YOU WIN!
            </h2>

            <div className="bg-slate-800 p-6 rounded-2xl border border-yellow-500 mb-8 w-full max-w-xs">
              <div className="flex justify-between items-center mb-2">
                <span className="text-slate-400">Final Score</span>
                <span className="text-2xl font-bold text-yellow-500">
                  {score}
                </span>
              </div>
            </div>

            <button
              onClick={startGame}
              className="px-8 py-4 bg-yellow-500 hover:bg-yellow-400 text-slate-900 font-black text-xl rounded-full transition-all transform hover:scale-105 active:scale-95 shadow-lg flex items-center gap-3"
            >
              <RotateCcw className="w-6 h-6" />
              PLAY AGAIN
            </button>
          </div>
        )}
      </div>

      <style>{`
        @keyframes shine {
            100% { transform: translateX(100%); }
        }
        .animate-shine {
            animation: shine 0.5s;
        }
      `}</style>
    </div>
  );
};

export default BoopItGame;
